#include "../../web/emu_api.c"
#define N 524288
static struct {unsigned pc,thumb,raw;uint64_t hits;} table[N];static uint64_t absent,irqs;
void trace_op(unsigned p,unsigned t,unsigned raw){unsigned h=((p>>1)^(p>>17)^(t?0x1234:0))&(N-1);unsigned tries=0;while(table[h].hits&&(table[h].pc!=p||table[h].thumb!=t)){if(++tries==32){absent++;return;}h=(h+1)&(N-1);}table[h].pc=p;table[h].thumb=t;table[h].hits++;table[h].raw=raw;}
static void run(unsigned n){while(n){unsigned k=n>50000?50000:n;unsigned r=emu_run(k);if(!r)break;n-=r;if(n%50000000==0)printf("remaining%u step%llu\n",n,(unsigned long long)machine.cpu.cycles);}}
int main(int c,char**v){setvbuf(stdout,NULL,_IOLBF,0);machine_ready=s5l_board_init(s5l_board_find("m68"),&machine,256u<<20);if(snapshot_load(&machine,".context/organizer-debug/clean-ready-home.snap"))return 2;machine.mtz1.uptime_ms=machine.timer.ticks/6000;reset_host_inputs();emu_release_inputs();s5l8900_set_direct_ram_writes(&machine,true);emu_touch(1,275,250);run(5000000);emu_touch(0,275,250);run(595000000);FILE*f=fopen(".context/speed-next/settings-profile.tsv","w");for(unsigned i=0;i<N;i++)if(table[i].hits)fprintf(f,"%08x\t%u\t%08x\t%llu\n",table[i].pc,table[i].thumb,table[i].raw,(unsigned long long)table[i].hits);fclose(f);printf("absent%llu irqs%llu end%llu\n",(unsigned long long)absent,(unsigned long long)irqs,(unsigned long long)machine.cpu.cycles);s5l8900_set_pre_step_hook(&machine,NULL,NULL,NULL,0);snapshot_save(&machine,".context/speed-next/settings-profile.snap");unsigned w,h;uint8_t*p=malloc(320*480*4);if(emu_frame(p,&w,&h)){f=fopen(".context/speed-next/settings-profile.ppm","wb");fprintf(f,"P6\n%u %u\n255\n",w,h);for(unsigned i=0;i<w*h;i++)fwrite(p+4*i,3,1,f);fclose(f);}release_machine();}
